const tally = {
  n: 0,
  add(amount) {
    this.n = this.n + amount;
  },
  total() {
    return this.n;
  },
};

// caller A uses only the methods
tally.add(2);
tally.add(3);
console.log(tally.total());

// caller B keeps using the same bundle, also via methods
tally.add(4);
console.log(tally.total());
